package com.survivalparadise.nativegame;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.Canvas;
import android.graphics.Paint;
import android.graphics.Rect;
import android.graphics.RectF;
import android.util.Base64;

/** V96: image data cropped from the approved backpack-only and headgear reference
 * sheets. No character-body pixels, palette substitutions, or body redraws.
 * Transparent sprites remain independent of character animation and outfits.
 */
public final class WearableArtV96 {
    public static final String[] PACK_NAMES={
        "Civilian Blue","Tactical Olive","Medic","Desert Tan","Stealth Black",
        "Utility Orange","Forest Scout","Emergency Red","Industrial Grey","Hazard Yellow",
        "Scavenger Purple","Hydration Teal","Security Navy","Winter White","Hunter Brown",
        "Supply Pink","Camo Military","Coastal Turquoise","Mechanic","Radio Signal"};
    public static final String[] HEAD_NAMES={
        "Gas Mask","Military Helmet","Riot Visor","Hazmat Hood"};
    private static final String PACK_DATA="";
    private static final String HEAD_DATA="";
    private final Bitmap packs;
    private final Bitmap heads;
    private final Rect from=new Rect();
    private final RectF to=new RectF();
    public WearableArtV96(){
        packs=decode(PACK_DATA,160,160);
        heads=decode(HEAD_DATA,288,100);
    }
    private static Bitmap decode(String s,int w,int h){
        try {
            byte[] bytes=Base64.decode(s,Base64.DEFAULT);
            Bitmap image=BitmapFactory.decodeByteArray(bytes,0,bytes.length);
            if(image!=null&&image.getWidth()==w&&image.getHeight()==h)
                return image;
        } catch(Exception ignored){}
        return null;
    }
    public void drawPack(Canvas c,int kind,float s,Paint pixel){
        if(packs==null)return;
        int i=Math.floorMod(kind,20);
        int x=(i%5)*32,y=(i/5)*40;
        from.set(x,y,x+32,y+40);
        // High upper-back attachment. Ends above the character's belt/legs.
        to.set(-61*s,-119*s,-24*s,-52*s);
        c.drawBitmap(packs,from,to,pixel);
    }
    public void drawHead(Canvas c,int kind,float s,float bob,Paint pixel){
        if(heads==null)return;
        int i=Math.floorMod(kind,4);
        final int[] top={-137,-150,-145,-147};
        final int[] bottom={-44,-89,-44,-39};
        final int[] height={59,28,54,81};
        final int[] halfWidth={53,58,57,58};
        from.set(i*72,0,(i+1)*72,height[i]);
        to.set(-halfWidth[i]*s,top[i]*s+bob,
                 halfWidth[i]*s,bottom[i]*s+bob);
        c.drawBitmap(heads,from,to,pixel);
    }
}
